import ctypes
import os

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# double gsl_cdf_hypergeometric_P(const unsigned int k, const unsigned int n1, const unsigned int n2, const unsigned int t);
gsl.gsl_cdf_hypergeometric_P.argtypes = [ctypes.c_uint, ctypes.c_uint, ctypes.c_uint, ctypes.c_uint]
gsl.gsl_cdf_hypergeometric_P.restype = ctypes.c_double

# Python wrapper function
def hypergeometric_cdf(k, n1, n2, t):
    if t > n1 + n2:
        raise ValueError("CDF_ERROR: t larger than population size")
    if k > t:
        return 1.0
    if k < 0:
        return 0.0
    return gsl.gsl_cdf_hypergeometric_P(k, n1, n2, t)

# Assertion tests
def assert_test():
    # Test case 1: Valid input
    assert abs(hypergeometric_cdf(5, 10, 20, 15) - 0.5) < 0.5, "Test case 1 failed"

    # Test case 2: Edge case where k >= n1
    assert hypergeometric_cdf(10, 10, 20, 15) == 1.0, "Test case 2 failed"

    # Test case 3: Edge case where k >= t
    assert hypergeometric_cdf(15, 10, 20, 15) == 1.0, "Test case 3 failed"

    # Test case 4: Invalid input where t > n1 + n2
    try:
        hypergeometric_cdf(5, 10, 20, 35)
    except ValueError as e:
        assert str(e) == "CDF_ERROR: t larger than population size", "Test case 4 failed"

if __name__ == "__main__":
    assert_test()
